async function main() {
  const customers = rawData.map(row => ({
    name: String(row[2]),
    ktpNumber: String(row[3]),
    address: String(row[4]),
    birthPlace: String(row[5]),
    birthDate: row[6] ? new Date(String(row[6])) : null,
    gender: String(row[7]),
    phone: String(row[8]),
    email: row[9] ? String(row[9]) : null,
    occupation: row[10] ? String(row[10]) : null,
    ktpFile: row[11] ? String(row[11]) : null,
    createdAt: row[13] ? new Date(String(row[13])) : new Date(),
    updatedAt: row[14] ? new Date(String(row[14])) : new Date(),
  }));

  console.log(`Seeding ${customers.length} customers...`);
  
  await prisma.customer.createMany({
    data: customers,
    skipDuplicates: true
  });

  console.log('Customers seeded successfully!');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
